function inserirSelecao($id,$idade,$opcoes=array()){
 global $db,$hoje;
 $dados=array_merge(array('id'=>$id,'nome'=>'Fêmea '.$id,'sexo'=>'Fêmea','status'=>0,'data_de_nascimento'=>$idade===null?null:$hoje->modify('-'.$idade.' months')->format('Y-m-d'),'mae'=>0,'terceiro_mae'=>0,'fbb'=>'FBB','tatuagem'=>'TAT'),$opcoes);
 $valores=array_map(function($v)use($db){return $v===null?'NULL':"'".$db->real_escape_string((string)$v)."'";},$dados);
 $db->query('INSERT INTO animais VALUES('.implode(',',$valores).')');
}
